const body = $input.first().json.body || $input.first().json;

// Handle two formats:
// 1. Facebook field_data array (forwarded via Zapier/Make)
// 2. Flat JSON (direct POST from website form or test)
let fields = {};

if (body.field_data && Array.isArray(body.field_data)) {
  for (const field of body.field_data) {
    fields[field.name] = field.values?.[0] || null;
  }
} else {
  fields = body;
}

// Generate a unique recordId
const recordId = body.id
  || body.lead_id
  || `webhook-${Date.now()}`;

return [{
  json: {
    // Lead contact details
    leadName:  fields['full_name']    || fields['name']          || null,
    leadEmail: fields['email']        || fields['email_address'] || null,
    leadPhone: fields['phone_number'] || fields['phone']         || null,

    // Qualification fields
    intent:    fields['are_you_looking_to_buy_sell_or_rent']
               || fields['intent']    || null,
    budget:    fields['what_is_your_budget_range']
               || fields['budget']    || null,
    timeline:  fields['what_is_your_buying_selling_timeline']
               || fields['timeline']  || null,
    situation: fields['what_best_describes_your_situation']
               || fields['situation'] || null,

    // Campaign metadata
    leadId:     body.id          || body.lead_id     || recordId,
    formId:     body.form_id     || null,
    adId:       body.ad_id       || null,
    adsetId:    body.adset_id    || null,
    campaignId: body.campaign_id || null,
    createdTime: new Date().toISOString(),

    // Stable unique identifier
    recordId:  recordId,
    timestamp: new Date().toISOString()
  }
}];

// ============================================================
// UPDATE THESE NODE NAMES IF YOU RENAME THEM ON THE CANVAS
const EXTRACT_NODE = 'Extract & Normalize Lead Details';
// ============================================================

const leadData = $(EXTRACT_NODE).first().json;
const inputJson = $input.first().json;

// Handle all possible Gemini response formats
let rawText = '';

if (inputJson.score && inputJson.email_body) {
  // Built-in Gemini node — already a parsed object
  rawText = JSON.stringify(inputJson);
} else if (typeof inputJson.output === 'string') {
  // Built-in Gemini node — string output field
  rawText = inputJson.output;
} else if (inputJson.candidates?.[0]?.content?.parts?.[0]?.text) {
  // HTTP Request node calling Gemini API directly
  rawText = inputJson.candidates[0].content.parts[0].text;
} else if (inputJson.content?.parts?.[0]?.text) {
  rawText = inputJson.content.parts[0].text;
}

// Strip markdown fences
const cleaned = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

// Parse with fallback
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    score: 'Warm',
    reasoning: 'AI parsing failed — manual review recommended.',
    email_subject: `Thanks for your enquiry, ${leadData.leadName || 'there'}!`,
    email_body: `Hi ${leadData.leadName || 'there'},\n\nThank you for reaching out. We received your enquiry and will be in touch shortly.`
  };
}

// HTML formatter — same pattern as all previous templates
function escapeHtml(text) {
  if (!text) return '';
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function formatEmailHtml(text) {
  if (!text) return '';
  const paragraphs = text
    .split(/\n\s*\n/)
    .map(p => p.replace(/\s+/g, ' ').trim())
    .filter(Boolean);
  return paragraphs.map(p => `<p>${escapeHtml(p)}</p>`).join('');
}

// Build agent notification HTML — includes campaign intelligence
const agentNotificationHtml = `
  <p><strong>${parsed.score === 'Hot' ? '🔥 Hot Lead' : '📋 New Lead'} — Facebook Ad</strong></p>
  <p>
    <strong>Name:</strong> ${escapeHtml(leadData.leadName || 'Unknown')}<br>
    <strong>Email:</strong> ${escapeHtml(leadData.leadEmail || 'Not provided')}<br>
    <strong>Phone:</strong> ${escapeHtml(leadData.leadPhone || 'Not provided')}<br>
    <strong>Intent:</strong> ${escapeHtml(leadData.intent || 'Not specified')}<br>
    <strong>Budget:</strong> ${escapeHtml(leadData.budget || 'Not specified')}<br>
    <strong>Timeline:</strong> ${escapeHtml(leadData.timeline || 'Not specified')}<br>
    <strong>Situation:</strong> ${escapeHtml(leadData.situation || 'Not specified')}
  </p>
  <p>
    <strong>AI Score:</strong> ${escapeHtml(parsed.score)}<br>
    <strong>Reasoning:</strong> ${escapeHtml(parsed.reasoning)}
  </p>
  <hr>
  <p><strong>📊 Campaign Intelligence</strong></p>
  <p>
    <strong>Facebook Lead ID:</strong> ${escapeHtml(leadData.leadId || 'N/A')}<br>
    <strong>Form ID:</strong> ${escapeHtml(leadData.formId || 'N/A')}<br>
    <strong>Ad ID:</strong> ${escapeHtml(leadData.adId || 'N/A (organic/test)')}<br>
    <strong>Campaign ID:</strong> ${escapeHtml(leadData.campaignId || 'N/A (organic/test)')}<br>
    <strong>Submitted:</strong> ${escapeHtml(leadData.createdTime || leadData.timestamp)}
  </p>
`;

return [{
  json: {
    // Lead details — from Extract node
    leadName:    leadData.leadName,
    leadEmail:   leadData.leadEmail,
    leadPhone:   leadData.leadPhone,
    intent:      leadData.intent,
    budget:      leadData.budget,
    timeline:    leadData.timeline,
    situation:   leadData.situation,
    // Facebook metadata
    leadId:      leadData.leadId,
    formId:      leadData.formId,
    adId:        leadData.adId,
    adsetId:     leadData.adsetId,
    campaignId:  leadData.campaignId,
    createdTime: leadData.createdTime,
    // AI qualification
    score:       parsed.score,
    reasoning:   parsed.reasoning,
    // Email content
    email_subject: parsed.email_subject,
    email_body:    formatEmailHtml(parsed.email_body),
    // Agent notification
    agentNotificationHtml,
    // Metadata
    recordId:  leadData.recordId,
    timestamp: leadData.timestamp
  }
}];

